            !control.matches('.slider.accessibilityControl')
          )
            return;
          const label =
            control.max === '360' ? '시점 회전' : control.min === '-90' ? '시점 기울기' : null;
          if (label) {
            control.setAttribute('aria-label', label);
            control.title = label;
          }
        }

