events.expression:
async (e) => {
            const input = e.currentTarget,
              f = input.files?.[0];
            if (!f) return;
            try {
              if (f.size > 2_000_000) throw Error('내용 파일은 2MB 이내로 나누어 주세요.');
              accept(importTemplates(await f.text()));
            } catch (error) {
              setError(error instanceof Error ? error.message : '내용을 가져오지 못했습니다.');
            } finally {
              input.value = '';
            }
          }

