    const chemical = /^(?:H2O|H2O2|CO2|O2|CH4)$/.test(part.text);
    const italic = /^[a-z]$/.test(part.tex) || /^[α-ωΑ-Ω]/.test(part.text);
    return <tspan className="concept-figure-math-token" fontStyle={italic ? 'italic' : 'normal'} key={index}>
      {indexed ? <><tspan>{part.text[0]}</tspan><tspan baselineShift="sub" fontSize="75%">{part.text.slice(1)}</tspan></>
        : chemical ? part.text.split(/([0-9]+)/).map((piece, i) => <tspan baselineShift={/^[0-9]+$/.test(piece) ? 'sub' : undefined} fontSize={/^[0-9]+$/.test(piece) ? '75%' : undefined} key={i}>{piece}</tspan>)
        : part.text}
    </tspan>;
  }

