    const nextFitSignature = JSON.stringify({ input, frame, spacing, layoutMode });
    const needsFit = fitSignature.current !== nextFitSignature;
    setBusy(true);
    setError('');
    const apply = (next: Record<string, CanvasPosition>) => {
      previous.current = next;
      setPositions(next);
      if (needsFit) {
        fitSignature.current = nextFitSignature;
        setFitting(true);
        setFitRevision((n) => n + 1);
      }
      setBusy(false);
    };
    if (hierarchical) {
      const next = layoutFlowBoxes(
