              const nextIndex = repeats.findIndex(repeat => repeat.id === last.nextId);
              repeats.splice(nextIndex < 0 ? Math.min(last.index, repeats.length) : nextIndex, 0, last.repeat);
              onChange({ repeats });
              setRemoved(previous => previous.slice(0, -1));
            }

() => {
            clearUiPerformance();
            clearRequestPerformance();
            setRequests([]);
            setNotice('측정값만 비웠습니다. 공부 기록은 유지됩니다.');
          }

onKeyDown.source:
(event) => {
            if (event.nativeEvent.isComposing) return;
            if (event.key === 'ArrowDown') {
              event.preventDefault();
              results.current?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus();
            }
            if (event.key === 'Enter' && visible.length === 1 && !visible[0].disabled) {
              event.preventDefault();
              setOpen(false);
              visible[0].run();
            }
          }

onRetry.source:
() => {
    try { const recovered = readRecall(data); setSession(recovered); setLoaded({ session: recovered, error: '' }); }
    catch (error) { setLoaded(value => ({ ...value, error: message(error) })); }
  }
